def shortest_path_islands(n: int, edges: list[list[int]]) -> int:
    from collections import defaultdict, deque
    adj = defaultdict(list)
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)
    q = deque([(1, 0)])
    visited = {1}
    while q:
        curr, dist = q.popleft()
        if curr == n:
            return dist
        for nxt in adj[curr]:
            if nxt not in visited:
                visited.add(nxt)
                q.append((nxt, dist + 1))
    return -1
